package ociresources

import (
	"testing"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/imagesearch"
)

// While registries answer one after the other, the row under the cursor stays
// the same row, identified by EntryKey + Repo and never by its index
// (DEVDESK-302, IS-04 c.8). datatable is untouched: the view does the tracking.

// cursorBrowser opens a browser on two registries and starts a search for
// "nginx". It returns the browser and the two entry keys.
func cursorBrowser(t *testing.T) (b *RegistryBrowser, keyA, keyB string) {
	t.Helper()
	b = newRegistryBrowser([]config.RegistryItem{
		{URL: "a.example.com", Alias: "a", Slug: "a"},
		{URL: "b.example.com", Alias: "b", Slug: "b"},
	}, nil, nil, 120, 30)
	if len(b.entries) != 2 {
		t.Fatalf("got %d entries, want 2", len(b.entries))
	}
	b.startImageSearch("nginx", b.entries)
	return b, b.entries[0].key, b.entries[1].key
}

func cursorImg(key, repo string) imagesearch.Image {
	return imagesearch.Image{EntryKey: key, Name: repo, Repo: repo}
}

func arrive(t *testing.T, b *RegistryBrowser, key string, repos ...string) {
	t.Helper()
	imgs := make([]imagesearch.Image, len(repos))
	for i, r := range repos {
		imgs[i] = cursorImg(key, r)
	}
	if !b.AddImageResults(ImageSearchResultMsg{Gen: b.gen, EntryKey: key, Images: imgs}) {
		t.Fatal("the result was refused")
	}
}

func assertSelected(t *testing.T, b *RegistryBrowser, key, repo string) {
	t.Helper()
	got, ok := b.searchTable.Selected()
	if !ok {
		t.Fatalf("nothing selected, want %s|%s", key, repo)
	}
	if got.img.EntryKey != key || got.img.Repo != repo {
		t.Errorf("selected %s|%s (cursor %d), want %s|%s",
			got.img.EntryKey, got.img.Repo, b.searchTable.Cursor(), key, repo)
	}
}

func TestSearchCursorStaysWhenRowsInsertBeforeTheSelection(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx-proxy", "nginx-ui")
	b.searchTable.SetCursor(1)
	assertSelected(t, b, keyB, "nginx-ui")

	// An exact match sorts before every prefix match.
	arrive(t, b, keyA, "nginx", "nginx-aaa")
	assertSelected(t, b, keyB, "nginx-ui")
}

func TestSearchCursorStaysWhenRowsInsertAfterTheSelection(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx", "nginx-proxy")
	b.searchTable.SetCursor(1)
	assertSelected(t, b, keyB, "nginx-proxy")

	arrive(t, b, keyA, "nginx-zzz", "my-nginx")
	assertSelected(t, b, keyB, "nginx-proxy")
}

func TestSearchCursorStaysWhenRowsInsertOnBothSides(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx-proxy")
	assertSelected(t, b, keyB, "nginx-proxy")

	arrive(t, b, keyA, "nginx", "nginx-zzz")
	assertSelected(t, b, keyB, "nginx-proxy")
}

// The same Repo from two registries is two rows: the key tells them apart.
func TestSearchCursorDistinguishesTheSameRepoOnTwoRegistries(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx")
	assertSelected(t, b, keyB, "nginx")

	arrive(t, b, keyA, "nginx") // sorts before b's row (label a < b)
	assertSelected(t, b, keyB, "nginx")
}

// A selected row that no longer exists is not an error: the cursor stays in
// range and on a row.
func TestSearchCursorWhenTheSelectedRowDisappears(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx", "nginx-proxy")
	b.searchTable.SetCursor(1)

	b.images = b.images[:1] // the selected row is gone
	b.rebuildSearchTable()
	if _, ok := b.searchTable.Selected(); !ok {
		t.Fatalf("no row selected after the selection disappeared (cursor %d)", b.searchTable.Cursor())
	}
	arrive(t, b, keyA, "nginx-aaa")
	if _, ok := b.searchTable.Selected(); !ok {
		t.Fatal("no row selected after a later arrival")
	}
}

func TestSearchCursorOnTheFirstRowReceivedWhenTheTableWasEmpty(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	// An empty answer first: the table stays empty.
	arrive(t, b, keyA)
	if _, ok := b.searchTable.Selected(); ok {
		t.Fatal("a row is selected in an empty table")
	}
	arrive(t, b, keyB, "nginx-ui", "nginx")
	// The first row of the order in force.
	assertSelected(t, b, keyB, "nginx")
	if c := b.searchTable.Cursor(); c != 0 {
		t.Errorf("cursor = %d, want 0", c)
	}
}

// A new search starts from an empty table: the cursor goes to the first row
// RECEIVED, and the selection of the previous search is not carried over, even
// when the same row comes back later (IS-04 c.8, "a new search returns the
// cursor to the first row").
func TestSearchCursorReturnsToTheFirstRowOnANewSearch(t *testing.T) {
	b, keyA, keyB := cursorBrowser(t)
	arrive(t, b, keyB, "nginx", "nginx-proxy", "nginx-ui")
	b.searchTable.SetCursor(2) // not the first row
	assertSelected(t, b, keyB, "nginx-ui")

	b.startImageSearch("nginx", b.entries)
	if _, ok := b.searchTable.Selected(); ok {
		t.Fatal("a row is selected right after a new search started")
	}

	// The first row received of the new search is selected, at index 0.
	arrive(t, b, keyA, "nginx-zzz", "nginx-zzzz")
	if c := b.searchTable.Cursor(); c != 0 {
		t.Errorf("cursor = %d, want 0 on the first row of a new search", c)
	}
	assertSelected(t, b, keyA, "nginx-zzz")

	// The old selection is not remembered: when its row comes back it sorts
	// before the cursor row, and the cursor stays on the row it was on.
	arrive(t, b, keyB, "nginx-ui")
	assertSelected(t, b, keyA, "nginx-zzz")
	if c := b.searchTable.Cursor(); c != 1 {
		t.Errorf("cursor = %d, want 1 (nginx-ui inserted before the selection)", c)
	}
}
package ociresources

import (
	"slices"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/imagesearch"
)

// The default order of the level 1 table is a pure function of the rows and
// the typed query: it must not depend on which registry answered first
// (DEVDESK-302, IS-04 c.5). Stars play no part in it.

func TestMatchTier(t *testing.T) {
	tests := []struct {
		name  string
		query string
		image string
		want  int
	}{
		{"exact", "nginx", "nginx", 0},
		{"exact ignores case of the name", "nginx", "NGINX", 0},
		{"exact ignores case of the query", "NGINX", "nginx", 0},
		{"last segment equals the query", "nginx", "bitnami/nginx", 1},
		{"last segment equals, deeper path", "nginx", "a/b/nginx", 1},
		{"last segment starts with the query", "nginx", "nginx-proxy", 2},
		{"last segment starts with the query, namespaced", "nginx", "bitnami/nginx-ingress", 2},
		{"name contains the query", "nginx", "my-nginx", 3},
		{"namespace contains the query only", "nginx", "nginxinc/proxy", 3},
		{"no match sorts after every tier", "nginx", "redis", 4},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := matchTier(tt.query, tt.image); got != tt.want {
				t.Errorf("matchTier(%q, %q) = %d, want %d", tt.query, tt.image, got, tt.want)
			}
		})
	}
}

func orderRow(name, label, key string, stars int) searchRow {
	return searchRow{
		img:   imagesearch.Image{Name: name, EntryKey: key, Stars: stars, HasStars: stars > 0},
		label: label,
	}
}

func orderIDs(rows []searchRow) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.label + "|" + r.img.Name + "|" + r.img.EntryKey
	}
	return out
}

func TestSortSearchRowsOrder(t *testing.T) {
	tests := []struct {
		name  string
		query string
		in    []searchRow
		want  []string
	}{
		{
			name:  "tiers first, then alphabetical",
			query: "nginx",
			in: []searchRow{
				orderRow("my-nginx", "hub", "k1", 0),
				orderRow("nginx-proxy", "hub", "k1", 0),
				orderRow("bitnami/nginx", "hub", "k1", 0),
				orderRow("nginx", "hub", "k1", 0),
				orderRow("redis", "hub", "k1", 0),
			},
			want: []string{
				"hub|nginx|k1", "hub|bitnami/nginx|k1", "hub|nginx-proxy|k1",
				"hub|my-nginx|k1", "hub|redis|k1",
			},
		},
		{
			name:  "alphabetical inside a tier is case-insensitive",
			query: "x",
			in: []searchRow{
				orderRow("xb", "hub", "k1", 0),
				orderRow("Xa", "hub", "k1", 0),
				orderRow("xc", "hub", "k1", 0),
			},
			want: []string{"hub|Xa|k1", "hub|xb|k1", "hub|xc|k1"},
		},
		{
			name:  "same name: alias, then EntryKey",
			query: "nginx",
			in: []searchRow{
				orderRow("nginx", "nexus", "k3", 0),
				orderRow("nginx", "hub", "k2", 0),
				orderRow("nginx", "hub", "k1", 0),
			},
			want: []string{"hub|nginx|k1", "hub|nginx|k2", "nexus|nginx|k3"},
		},
		{
			name:  "stars do not influence the order",
			query: "nginx",
			in: []searchRow{
				orderRow("nginx-b", "hub", "k1", 9000),
				orderRow("nginx-a", "hub", "k1", 1),
			},
			want: []string{"hub|nginx-a|k1", "hub|nginx-b|k1"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rows := slices.Clone(tt.in)
			sortSearchRows(tt.query, rows)
			if got := orderIDs(rows); !slices.Equal(got, tt.want) {
				t.Errorf("order = %v, want %v", got, tt.want)
			}
		})
	}
}

// TestSortSearchRowsIgnoresArrivalOrder feeds the same rows, as several
// registries would deliver them, in every order: the result is one and the
// same.
func TestSortSearchRowsIgnoresArrivalOrder(t *testing.T) {
	hub := []searchRow{
		orderRow("nginx", "hub", "kh", 100),
		orderRow("bitnami/nginx", "hub", "kh", 5),
		orderRow("nginx-proxy", "hub", "kh", 0),
	}
	nexus := []searchRow{
		orderRow("nginx", "nexus", "kn", 0),
		orderRow("my-nginx", "nexus", "kn", 0),
		orderRow("team/nginx", "nexus", "kn", 0),
	}
	quay := []searchRow{
		orderRow("nginx", "quay", "kq", 0),
		orderRow("nginx-unprivileged", "quay", "kq", 0),
	}
	registries := [][]searchRow{hub, nexus, quay}
	perms := [][]int{{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}}

	var first []string
	for _, p := range perms {
		var rows []searchRow
		for _, i := range p {
			rows = append(rows, registries[i]...)
		}
		sortSearchRows("nginx", rows)
		got := orderIDs(rows)
		if first == nil {
			first = got
			continue
		}
		if !slices.Equal(got, first) {
			t.Errorf("arrival order %v gave %v, want %v", p, got, first)
		}
	}
	// The order itself is pinned too, not only its stability.
	want := []string{
		"hub|nginx|kh", "nexus|nginx|kn", "quay|nginx|kq",
		"hub|bitnami/nginx|kh", "nexus|team/nginx|kn",
		"hub|nginx-proxy|kh", "quay|nginx-unprivileged|kq",
		"nexus|my-nginx|kn",
	}
	if !slices.Equal(first, want) {
		t.Errorf("order = %v, want %v", first, want)
	}
}

// TestAnswerOrderDoesNotChangeTheTable feeds the hub then nexus, then the
// reverse, through the browser: the table shows the same rows in the same
// order.
func TestAnswerOrderDoesNotChangeTheTable(t *testing.T) {
	run := func(first, second string) []string {
		m := lvl1SearchingModel(t)
		answers := map[string][]string{
			"hub":  {"nginx-proxy", "nginx", "bitnami/nginx"},
			"prod": {"my-nginx", "nginx", "redis"},
		}
		m = lvl1Answer(t, m, first, answers[first]...)
		m = lvl1Answer(t, m, second, answers[second]...)
		return orderIDs(m.registryBrowser.searchTable.Items())
	}
	a, b := run("hub", "prod"), run("prod", "hub")
	if len(a) != 6 || !slices.Equal(a, b) {
		t.Errorf("hub then prod = %v, prod then hub = %v", a, b)
	}
